func msg(key string) string {
	code := strings.ToLower(os.Getenv("DCC_LANG"))
	if code == "" {
		code = osLang()
	}
	if len(code) > 2 {
		code = code[:2]
	}
	if m, ok := nativeMsgs[code]; ok && m[key] != "" {
		return m[key]
	}
	return nativeMsgs["en"][key]
}
